from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self._capacity = max(0, capacity)
        self._ttl = ttl
        self._clock = clock
        self._store = OrderedDict()
        self._stats = {
            "hits": 0,
            "misses": 0,
            "evictions": 0,
            "expirations": 0,
        }

    def put(self, key, value) -> None:
        now = self._clock()

        if self._capacity == 0:
            return

        if key in self._store:
            self._store[key] = (value, now + self._ttl)
            self._store.move_to_end(key)
            return

        if len(self._store) + 1 > self._capacity:
            self._purge_expired(now)
            if len(self._store) >= self._capacity:
                self._store.popitem(last=False)
                self._stats["evictions"] += 1

        self._store[key] = (value, now + self._ttl)

    def get(self, key, default=None):
        now = self._clock()

        if key not in self._store:
            self._stats["misses"] += 1
            return default

        value, expiry = self._store[key]

        if now >= expiry:
            del self._store[key]
            self._stats["misses"] += 1
            self._stats["expirations"] += 1
            return default

        self._store.move_to_end(key)
        self._stats["hits"] += 1
        return value

    def __len__(self) -> int:
        now = self._clock()
        return sum(1 for _, expiry in self._store.values() if now < expiry)

    def stats(self) -> dict:
        return {
            "hits": self._stats["hits"],
            "misses": self._stats["misses"],
            "evictions": self._stats["evictions"],
            "expirations": self._stats["expirations"],
        }

    def _purge_expired(self, now) -> None:
        expired = [key for key, (_, expiry) in self._store.items() if now >= expiry]
        if expired:
            for key in expired:
                del self._store[key]
            self._stats["expirations"] += len(expired)
