import re

_DURATION_RE = re.compile(
    r"(?:\s*([0-9]+)h)?(?:\s*([0-9]+)m)?(?:\s*([0-9]+)s)?\s*",
    re.IGNORECASE | re.ASCII,
)

def parse_duration(s: str) -> int:
    if not s.strip():
        raise ValueError("duration string must not be empty")

    match = _DURATION_RE.fullmatch(s)
    if match is None:
        raise ValueError(f"invalid duration string: {s!r}")

    hours, minutes, seconds = match.groups()

    return (
        (int(hours) if hours is not None else 0) * 3600
        + (int(minutes) if minutes is not None else 0) * 60
        + (int(seconds) if seconds is not None else 0)
    )
