import re
import unicodedata


def slugify(title: str, max_len: int = 50) -> str:
    normalized = unicodedata.normalize("NFD", title)
    ascii_text = "".join(ch for ch in normalized if ch.isascii())

    slug = re.sub(r"[^a-z0-9]+", "-", ascii_text.lower()).strip("-")

    if not slug or max_len <= 0:
        return ""

    if len(slug) <= max_len:
        return slug

    words = slug.split("-")

    if len(words[0]) > max_len:
        return words[0][:max_len]

    kept = [words[0]]
    current_len = len(words[0])

    for word in words[1:]:
        candidate_len = current_len + 1 + len(word)
        if candidate_len <= max_len:
            kept.append(word)
            current_len = candidate_len
        else:
            break

    return "-".join(kept)
