import re

_AMOUNT_RE = re.compile(
    r"^\s*(?P<sign1>[+-]?)\s*(?:\$)?\s*(?P<sign2>[+-]?)\s*"
    r"(?P<number>\d{1,3}(?:,\d{3})*(?:\.\d*)?|\d+(?:\.\d*)?|\.\d+)\s*$"
)


def _parse_amount(value: object) -> float | None:
    if not isinstance(value, str):
        return None

    match = _AMOUNT_RE.fullmatch(value)
    if match is None:
        return None

    sign1 = match.group("sign1")
    sign2 = match.group("sign2")

    if sign1 and sign2:
        return None

    number = match.group("number").replace(",", "")

    try:
        amount = float(number)
    except (ValueError, OverflowError):
        return None

    sign = sign1 or sign2
    if sign == "-":
        return -amount

    return amount


def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    if n <= 0:
        return []

    totals: dict[str, float] = {}
    display_names: dict[str, str] = {}

    for row in rows:
        if not isinstance(row, dict):
            continue

        customer = row.get("customer")
        if not isinstance(customer, str):
            continue

        name = customer.strip()
        if not name:
            continue

        amount = _parse_amount(row.get("amount"))
        if amount is None:
            continue

        key = name.casefold()
        if key not in display_names:
            display_names[key] = name

        totals[key] = totals.get(key, 0.0) + amount

    results = []
    for key, total in totals.items():
        rounded_total = round(total, 2)
        if rounded_total == 0:
            rounded_total = 0.0
        results.append((display_names[key], rounded_total))

    results.sort(key=lambda item: (-item[1], item[0]))
    return results[:n]
